test('github: branchExists probes the head repo fork PRs (gh-1057)', function () {
   // gh-1057 (live fa pr-1591): a fork's branch can never exist in the
   // base repo — probing the base is a guaranteed 404 that parks a
   // restored fork forever. branchExists(name, headFull) redirects the
   // same snapshot+probe machinery at the fork; absent/malformed/same-
   // repo specs keep the base probe (today's behavior).
