test('github: branchExists probes the head repo fork PRs (gh-1057)', function () {
   // gh-1057 (live fa pr-1591): a fork's branch can never exist in the
   // base repo — probing the base is a guaranteed 404 that parks a
   // restored fork forever. branchExists(name, headFull) redirects the
   // same snapshot+probe machinery at the fork; absent/malformed/same-
   // repo specs keep the base probe (today's behavior).
   var probed = [];
   var listed = [];
   var p = loadProvider('github', {
       github_list_branches: function (args) {
           listed.push(args.workspace + '/' + args.repository);
           if (args.repository === 'base-repo') {
               return [{ name: 'main', commit: { sha: 'm' }]; // fork branch NOT here
           }
           return [{ name: 'fix/fork-branch', commit: { sha: 'f' }];
       },
       cli_execute_command: function (args) {
           probed.push(args.command);
           throw new Error('404 Not Found');
       }
   });
   // fork branch present in the FORK, absent in base — must resolve true
   assert.equal(p.branchExists('fix/fork-branch', 'forko/forkr'), true,
       'the fork probe answers from the fork snapshot, not the base 404');
   assert.equal(listed.indexOf('forko/forkr') !== -1, true,
       'the branch listing ran against the head repo');
   // branch gone in BOTH repos — still false
   assert.equal(p.branchExists('gone/everywhere', 'forko/forkr'), false,
       'a fork probe 404 keeps the bench verdict for a really-dead head');
   assert.equal(p.branchExists('gone/everywhere'), false,
       'no head spec — the base probe (unchanged legacy behavior)');
   // same-repo spec is a no-op redirect
   assert.equal(p.branchExists('main', 'mygroup/my-repo'), true,
       'a same-repo head spec keeps the base snapshot answer');
   // malformed spec falls back to base (fail-safe)
   assert.equal(p.branchExists('main', 'not-a-repo-spec'), true,
       'a malformed head spec falls back to the base probe');
});
