   });
   // fork branch present in the FORK, absent in base — must resolve true
   assert.equal(p.branchExists('fix/fork-branch', 'forko/forkr'), true,
       'the fork probe answers from the fork snapshot, not the base 404');
   assert.equal(listed.indexOf('forko/forkr') !== -1, true,
       'the branch listing ran against the head repo');
   // branch gone in BOTH repos — still false
